import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class Nights {
    public static void main(String[] args) {
        LocalDate start = LocalDate.parse("2026-05-11");
        LocalDate end = start.plusDays(7);

        // the original object never changes
        System.out.println(start); // 2026-05-11
        System.out.println(end);   // 2026-05-18

        // a count in days, the usual stay length question
        System.out.println(ChronoUnit.DAYS.between(start, end)); // 7

        // comparisons are methods, not operators
        System.out.println(end.isAfter(start));  // true
        System.out.println(start.isBefore(end)); // true
    }
}

// File: StampDate.java
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public class StampDate {
    public static void main(String[] args) {
        LocalDate date = LocalDate.of(2026, 5, 18);

        // the locale fixes the month name, so another machine cannot change it
        DateTimeFormatter display =
                DateTimeFormatter.ofPattern("dd MMM yyyy", Locale.ENGLISH);
        System.out.println(date.format(display)); // 18 May 2026

        // parsing needs the same pattern that produced the text
        System.out.println(LocalDate.parse("18 May 2026", display).equals(date)); // true

        // yyyy is the year, MM the month, dd the day; mm would be minutes
        System.out.println(date.format(DateTimeFormatter.ISO_LOCAL_DATE)); // 2026-05-18
    }
}

// File: Guest.java
public class Guest {
    record Row(String email, int nights) {
        // A compact constructor checks the values before the fields are set
        Row {
            if (email == null || !email.contains("@")) {
                throw new IllegalArgumentException("bad email");
            }
            if (nights < 1) {
                throw new IllegalArgumentException("bad nights: " + nights);
            }
        }

        // a derived value is a method, not a stored field
        int price(int nightly) {
            return nights * nightly;
        }
    }

    public static void main(String[] args) {
        Row row = new Row("anna@example.com", 3);
        System.out.println(row.email());   // anna@example.com
        System.out.println(row.price(80)); // 240

        // equals compares the components, so it is data equality
        System.out.println(row.equals(new Row("anna@example.com", 3))); // true
        System.out.println(row); // Row[email=anna@example.com, nights=3]
    }
}

