import java.util.Scanner;

public class ReadTokens {
    public static void main(String[] args) {
        // Scanner splits on whitespace by default
        Scanner scanner = new Scanner("4 12 7");
        int count = scanner.nextInt();
        int sum = 0;
        while (scanner.hasNextInt()) {
            sum += scanner.nextInt();
        }
        System.out.println(count + " " + sum); // 4 19
        scanner.close();

        // nextInt leaves the line break in the buffer, so clear it first
        Scanner lines = new Scanner("42\nAnna");
        int number = lines.nextInt();
        lines.nextLine();               // swallows the empty rest of the line
        System.out.println(number + " " + lines.nextLine()); // 42 Anna
        lines.close();
    }
}

// File: RoomTypes.java
public class RoomTypes {
    enum Type {
        SINGLE(80), DOUBLE(120); // each constant is an instance

        private final int price; // fields come after the constants

        Type(int price) { // the constructor is implicitly private
            this.price = price;
        }

        int total(int nights) {
            return price * nights;
        }

        static Type of(String name) { // a clear failure instead of null
            return Type.valueOf(name.toUpperCase());
        }
    }

    public static void main(String[] args) {
        Type type = Type.of("double");
        System.out.println(type);                 // DOUBLE
        System.out.println(type.total(3));        // 360
        System.out.println(type.ordinal());       // 1
        System.out.println(Type.values().length); // 2
    }
}

