import java.util.List;

public class Largest {
    // The bound allows compareTo and keeps the return type as T
    static <T extends Comparable<T>> T largest(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) {
                best = item;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(largest(List.of(4, 19, 7)));               // 19
        System.out.println(largest(List.of("Eger", "Gyor", "Baja"))); // Gyor
    }
}

// File: Pool.java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class Pool {
    public static void main(String[] args) throws InterruptedException {
        // Two worker threads, reused for every submitted task
        ExecutorService pool = Executors.newFixedThreadPool(2);
        for (int i = 1; i <= 4; i++) {
            int id = i; // a lambda captures only effectively final values
            pool.submit(() -> System.out.println("task " + id));
        }

        // shutdown refuses new tasks, awaitTermination waits for the running ones
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
        System.out.println("done"); // always last
    }
}

