import java.util.HashSet;
import java.util.Set;

public class UniqueEmails {
    public static void main(String[] args) {
        Set<String> seen = new HashSet<>();

        // add returns false when the value was already present
        System.out.println(seen.add("anna@example.com")); // true
        System.out.println(seen.add("bela@example.com")); // true
        System.out.println(seen.add("anna@example.com")); // false

        System.out.println(seen.size());                       // 2
        System.out.println(seen.contains("bela@example.com")); // true

        // iteration order is not insertion order
        for (String email : seen) {
            System.out.println(email);
        }
    }
}

// File: Band.java
public class Band {
    enum Season { LOW, HIGH }

    public static void main(String[] args) {
        int nights = 5;

        // a comma separates labels, there is no fallthrough and no break
        String band = switch (nights) {
            case 1, 2 -> "weekend";
            case 3, 4, 5 -> {
                String label = "midweek";
                yield label; // a block case returns with yield
            }
            default -> "long";
        };
        System.out.println(band); // midweek

        // over an enum the switch must cover every constant
        Season season = Season.HIGH;
        int price = switch (season) {
            case LOW -> 80;
            case HIGH -> 160;
        };
        System.out.println(price); // 160
    }
}

